import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { createClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

const CopyScheduleSchema = z.object({
  /** Target artist ID to copy the schedule to. */
  target_artist_id: z.string().uuid(),
  /**
   * If true, delete existing slots on the target before copying (replace mode).
   * If false (default), merge — only inserts slots not already present on target.
   */
  replace: z.boolean().optional().default(false),
  /**
   * Effective date for the new slots on the target. Defaults to today.
   */
  effective_from: z.string().regex(/^\d{4}-\d{2}-\d{2}$/).optional(),
})

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  // Only owner/admin can copy schedules between artists
  if (authUser.role !== 'owner' && authUser.role !== 'admin') {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const { id: sourceArtistId } = await params

  const body = CopyScheduleSchema.safeParse(await request.json())
  if (!body.success) {
    return NextResponse.json({ error: body.error.flatten() }, { status: 400 })
  }

  if (body.data.target_artist_id === sourceArtistId) {
    return NextResponse.json({ error: 'Source and target artists must be different' }, { status: 400 })
  }

  try {
    const supabase = await createClient()

    // M4 FIX: delegate to atomic SECURITY DEFINER RPC that runs DELETE + INSERT
    // in a single transaction and respects merge semantics.
    const { data, error: rpcError } = await supabase.rpc('copy_artist_schedule', {
      p_source_artist_id: sourceArtistId,
      p_target_artist_id: body.data.target_artist_id,
      p_replace:          body.data.replace,
      p_effective_from:   body.data.effective_from ?? new Date().toISOString().slice(0, 10),
    })

    if (rpcError) {
      logger.error({ err: rpcError, sourceArtistId }, 'copy_artist_schedule RPC failed')
      return NextResponse.json({ error: 'Failed to copy schedule' }, { status: 500 })
    }

    if (!data) {
      return NextResponse.json({ error: 'Failed to copy schedule' }, { status: 500 })
    }

    const result = data as { error?: string; copied?: number; replace?: boolean }

    if (result.error === 'source_artist_not_found') {
      return NextResponse.json({ error: 'Source artist not found' }, { status: 404 })
    }
    if (result.error === 'target_artist_not_found') {
      return NextResponse.json({ error: 'Target artist not found' }, { status: 404 })
    }
    if (result.error === 'source_has_no_slots') {
      return NextResponse.json({ error: 'Source artist has no schedule slots to copy' }, { status: 422 })
    }
    if (result.error === 'forbidden') {
      return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
    }
    if (result.error) {
      return NextResponse.json({ error: result.error }, { status: 500 })
    }

    return NextResponse.json({ data: { copied: result.copied ?? 0 } }, { status: 201 })
  } catch (err) {
    logger.error({ err }, 'copy-schedule unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import { createClient } from '@/lib/supabase/server'
import { cacheGet, cacheSet } from '@/lib/cache'
import { logger } from '@/lib/logger'

/**
 * Updates studio_members.last_active_at for the current user in the given studio.
 *
 * Throttled: writes to DB at most once per 60 seconds per (user, studio) pair.
 * The Upstash cache key acts as a write-gate — if set, skip the DB write.
 *
 * Failures are silent — do NOT toast or throw.
 */
export async function updateLastActive(studioId: string): Promise<void> {
  try {
    const supabase = await createClient()
    const {
      data: { user },
    } = await supabase.auth.getUser()
    if (!user) return

    // C3 / M8 FIX: Upstash throttle — at most 1 DB write per 60s per (user, studio)
    const cacheKey = `last_active:${user.id}:${studioId}`
    const cached = await cacheGet<string>(cacheKey)
    if (cached) return

    await supabase
      .from('studio_members')
      .update({ last_active_at: new Date().toISOString() })
      .eq('studio_id', studioId)
      .eq('user_id', user.id)
      .is('deactivated_at', null)

    // Set gate after successful write; ignore errors (cache failure != app failure)
    await cacheSet(cacheKey, '1', 60)
  } catch (err) {
    logger.warn({ err }, 'updateLastActive failed — suppressed')
  }
}

