import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

export async function POST(
  _request: NextRequest,
  { params }: { params: Promise<{ token: string }> },
) {
  const { token } = await params

  // Auth check — must be logged in to accept
  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  try {
    // C2 FIX: accept_team_invite RPC now returns artist_id + commission_default_pct
    // AND performs the commission patch internally under SECURITY DEFINER.
    // The route no longer needs a service-role client write.
    const { data, error } = await supabase.rpc('accept_team_invite', {
      p_invite_token: token,
    })

    if (error) {
      logger.error({ err: error, token }, 'accept_team_invite RPC failed')
      return NextResponse.json({ error: 'Failed to accept invite' }, { status: 500 })
    }

    type AcceptResult = {
      error?: string
      status?: string
      studio_id?: string
      studio_name?: string
      role?: string
      artist_id?: string | null
      commission_default_pct?: number | null
      invite_id?: string
      redirect?: string
    }

    const result = data as AcceptResult | null

    // RPC returns an error field for known failure modes
    if (result?.error) {
      if (result.error === 'email_mismatch') {
        return NextResponse.json({ error: 'email_mismatch' }, { status: 409 })
      }
      if (result.error === 'already_a_member') {
        return NextResponse.json({ error: 'already_a_member' }, { status: 409 })
      }
      if (result.error === 'invite_not_found') {
        return NextResponse.json({ error: 'invite_not_found' }, { status: 404 })
      }
      if (result.error === 'invite_expired' || result.error === 'expired') {
        return NextResponse.json({ error: 'expired' }, { status: 410 })
      }
      if (result.error === 'not_authenticated') {
        return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
      }
      logger.error({ result, token }, 'accept_team_invite returned error')
      return NextResponse.json({ error: 'Failed to accept invite' }, { status: 500 })
    }

    return NextResponse.json({ data: result })
  } catch (err) {
    logger.error({ err, token }, 'team-invite accept unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

